orm-label fw-bold small text-dark">Pelaksana (Dokter/Perawat)</label>                     <select class="form-select select2-pegawai" id="pelaksana_id" name="pelaksana_id" style="width: 100%;">                         <option value="">-- Pilih Pelaksana --</option>                         @foreach($master_pegawai as $peg)                             <option value="{{ $peg->id }}" {{ $pendaftaran->dokter_id == $peg->id ? 'selected' : '' }}>{{ $peg->nama_pegawai }}</option>                         @endforeach                     </select>                 </div>                  <div class="row mb-4">                     <div class="col-8">                         <label class="form-label fw-bold small text-dark">Tarif (Rp)</label>                         <input type="number" class="form-control bg-light" id="tarif" name="tarif" value="0" readonly>                     </div>                     <div class="col-4">                         <label class="form-label fw-bold small text-dark">Qty</label>                         <input type="number" class="form-control" id="qty" name="qty" value="1" min="1">                     </div>                 </div>                  <button type="submit" class="btn btn-success text-white w-100 shadow-sm" id="btnSimpanTindakan">                     <i class="fas fa-plus me-1"></i> Tambahkan ke Daftar                 </button>             </form>         </div>     </div>      <!-- Tabel Daftar Tindakan -->     <div class="col-md-8 mb-4">         <div class="card-custom p-4 shadow-sm border-0 rounded-3 h-100">             <h6 class="fw-bold mb-3 border-bottom pb-2 text-dark"><i class="fas fa-clipboard-list me-2 text-primary"></i>Daftar Tindakan Diberikan</h6>                          <div class="table-responsive">                 <table class="table table-hover table-striped align-middle" id="tabelTindakanDetail" style="border-top: 2px solid #e9ecef; border-bottom: 1px solid #e9ecef;">                     <thead>                         <tr>                             <th width="5%" class="text-center text-dark" style="background: transparent; border-bottom: 2px solid #dee2e6;">No</th>                             <th width="35%" class="text-dark" style="background: transparent; border-bottom: 2px solid #dee2e6;">Nama Tindakan</th>                             <th width="20%" class="text-dark" style="background: transparent; border-bottom: 2px solid #dee2e6;">Pelaksana</th>                             <th width="15%" class="text-end text-dark" style="background: transparent; border-bottom: 2px solid #dee2e6;">Tarif</th>                             <th width="5%" class="text-center text-dark" style="background: transparent; border-bottom: 2px solid #dee2e6;">Qty</th>                             <th width="15%" class="text-end text-dark" style="background: transparent; border-bottom: 2px solid #dee2e6;">Subtotal</th>                             <th width="5%" class="text-center text-dark" style="background: transparent; border-bottom: 2px solid #dee2e6;"><i class="fas fa-cog"></i></th>                         </tr>                     </thead>                     <tbody>                         @php $total_biaya = 0; @endphp                         @forelse($tindakans as $index => $item)                         @php $total_biaya += $item->subtotal; @endphp                         <tr data-id="{{ $item->id }}">                             <td class="text-center fw-bold">{{ $index + 1 }}</td>                             <td class="fw-bold">{{ $item->tindakan ? $item->tindakan->nama_tindakan : 'Dihapus' }}</td>                             <td>{{ $item->pelaksana ? $item->pelaksana->nama_pegawai : '-' }}</td>                             <td class="text-end">{{ number_format($item->tarif, 0, ',', '.') }}</td>                             <td class="text-center">{{ $item->qty }}</td>                             <td class="text-end fw-bold">{{ number_format($item->subtotal, 0, ',', '.') }}</td>                             <td class="text-center">                                 <button class="btn btn-sm btn-danger btnHapusTindakan" data-id="{{ $item->id }}" title="Hapus">                                     <i class="fas fa-trash-alt"></i>                                 </button>                             </td>                         </tr>                         @empty                         <tr id="rowKosong">                             <td colspan="7" class="text-center text-muted py-3">Belum ada tindakan yang diinput.</td>                         </tr>                         @endforelse                     </tbody>                     <tfoot style="background-color: #f8f9fa;">                         <tr>                             <th colspan="5" class="text-end fs-6 text-dark border-0">TOTAL BIAYA</th>                             <th class="text-end fs-5 text-dark fw-bold border-0" id="totalBiayaLabel">Rp {{ number_format($total_biaya, 0, ',', '.') }}</th>                             <th class="border-0"></th>                         </tr>                     </tfoot>                 </table>             </div>         </div>     </div> </div>  <link href="https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/css/select2.min.css" rel="stylesheet" /> <script src="https://cdn.jsdelivr.net/npm/select2@4.1.0-rc.0/dist/js/select2.min.js"></script>  <script> $(document).ready(function () {     $('.select2-tindakan').select2({ placeholder: "-- Ketik Nama Tindakan --" });     $('.select2-pegawai').select2({ placeholder: "-- Pilih Pelaksana --" });      function formatRupiah(angka) {         return angka.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");     }          function hitungTotal() {         let total = 0;         $('#tabelTindakanDetail tbody tr').not('#rowKosong').each(function() {             let subtotalStr = $(this).find('td:eq(5)').text().replace(/\./g, '');             total += parseInt(subtotalStr) || 0;         });         $('#totalBiayaLabel').text('Rp ' + formatRupiah(total));     }      function renumber() {         let count = 0;         $('#tabelTindakanDetail tbody tr').not('#rowKosong').each(function () {             count++;             $(this).find('td:first').text(count);         });         if (count === 0) {             $('#tabelTindakanDetail tbody').html('<tr id="rowKosong"><td colspan="7" class="text-center text-muted py-3">Belum ada tindakan yang diinput.</td></tr>');         }     }      // Auto get tarif based on selected tindakan & penjamin     $('#tindakan_id').change(function() {         let tindakan_id = $(this).val();         let penjamin_id = $('#penjamin_id').val();         if(tindakan_id) {             $.ajax({                 url: '/transaksi-tindakan/api/get-tarif',                 type: 'GET',                 data: { tindakan_id: tindakan_id, penjamin_id: penjamin_id },                 success: function(res) {                     $('#tarif').val(res.harga);                 }             });         } else {             $('#tarif').val(0);         }     });      $('#formTindakan').on('submit', function (e) {         e.preventDefault();         $('.is-invalid').removeClass('is-invalid');                  let btn = $('#btnSimpanTindakan');         let originalText = btn.html();         btn.html('<i class="fas fa-spinner fa-spin"></i> Menyimpan...').prop('disabled', true);          $.ajax({             url: '/transaksi-tindakan',              type: 'POST',              data: $(this).serialize(),             success: function (res) {                 btn.html(originalText).prop('disabled', false);                 $('#alertBox').removeClass('d-none alert-danger').addClass('alert-success').text(res.message).show();                 setTimeout(() => $('#alertBox').addClass('d-none'), 3000);                                  // Reset form                 $('#tindakan_id').val('').trigger('change');                 $('#qty').val(1);                                  // Add to table                 $('#rowKosong').remove();                 let item = res.data;                 let namaTindakan = item.tindakan ? item.tindakan.nama_tindakan : '-';                 let namaPelaksana = item.pelaksana ? item.pelaksana.nama_pegawai : '-';                                  let newRow = `<tr data-id="${item.id}">                     <td class="text-center">0</td>                     <td class="fw-bold">${namaTindakan}</td>                     <td>${namaPelaksana}</td>                     <td class="text-end">${formatRupiah(item.tarif)}</td>                     <td class="text-center">${item.qty}</td>                     <td class="text-end fw-bold">${formatRupiah(item.subtotal)}</td>                     <td class="text-center">                         <button class="btn btn-sm btn-danger btnHapusTindakan" data-id="${item.id}" title="Hapus">                             <i class="fas fa-times"></i>                         </button>                     </td>                 </tr>`;                                  $('#tabelTindakanDetail tbody').prepend(newRow);                 renumber();                 hitungTotal();             },             error: function (xhr) {                 btn.html(originalText).prop('disabled', false);                 if (xhr.status === 422) {                     let errors = xhr.responseJSON.errors;                     $.each(errors, function (field, messages) {                         if(field == 'tindakan_id') {                             $('#' + field).next('.select2-container').addClass('is-invalid');                             $('#err_' + field).text(messages[0]).show();                         }                     });                 } else {                     $('#alertBox').removeClass('d-none alert-success').addClass('alert-danger').text('Terjadi kesalahan server!').show();                 }             }         });     });      $(document).on('click', '.btnHapusTindakan', function () {         if(confirm('Yakin ingin menghapus tindakan ini?')) {             let id = $(this).data('id');             let row = $(this).closest('tr');                          $.ajax({                 url: '/transaksi-tindakan/' + id,                  type: 'DELETE',                 data: { _token: $('meta[name="csrf-token"]').attr('content') },                 success: function (res) {                     row.fadeOut(300, function() {                         $(this).remove();                         renumber();                         hitungTotal();                     });                 }             });         }     });  }); </script> @endsection
